schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "faion://claude-md-creation-quality/output.schema.json",
  "title": "CLAUDE.md quality record",
  "type": "object",
  "required": [
    "repo", "layout", "root_file", "secrets", "commands", "imports", "local_scope",
    "prohibitions", "emphasis_ratio", "refs_check", "reviewer", "evidence"
  ],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "repo": {"type": "string", "pattern": "^[A-Za-z0-9._-]+/[A-Za-z0-9._-]+$"},
    "layout": {"type": "string", "enum": ["single-package", "multi-package"]},
    "root_file": {
      "type": "object",
      "required": ["line_budget", "budget_declared_in_first_comment", "line_count", "within_budget", "ci_line_check"],
      "additionalProperties": false,
      "properties": {
        "line_budget": {"type": "integer", "minimum": 10, "maximum": 300},
        "budget_declared_in_first_comment": {"type": "boolean", "const": true},
        "line_count": {"type": "integer", "minimum": 1},
        "within_budget": {"type": "boolean", "const": true},
        "ci_line_check": {"type": "boolean", "const": true}
      }
    },
    "secrets": {
      "type": "object",
      "required": ["scanner", "runs_in_ci", "runs_in_pre_commit", "clean", "referenced_by_name_only"],
      "additionalProperties": false,
      "properties": {
        "scanner": {"type": "string", "enum": ["gitleaks", "trufflehog"]},
        "runs_in_ci": {"type": "boolean", "const": true},
        "runs_in_pre_commit": {"type": "boolean", "const": true},
        "clean": {"type": "boolean", "const": true},
        "referenced_by_name_only": {"type": "boolean", "const": true}
      }
    },
    "commands": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["invocation", "verbatim", "exit_code"],
        "additionalProperties": false,
        "properties": {
          "invocation": {"type": "string", "minLength": 2, "not": {"pattern": "(?i)^(run|execute|start) the "}},
          "verbatim": {"type": "boolean", "const": true},
          "exit_code": {"type": "integer", "const": 0}
        }
      }
    },
    "imports": {
      "type": "object",
      "required": ["pasted_repo_content", "entries"],
      "additionalProperties": false,
      "properties": {
        "pasted_repo_content": {"type": "boolean", "const": false},
        "entries": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["path", "exists", "hop_depth"],
            "additionalProperties": false,
            "properties": {
              "path": {"type": "string", "minLength": 1},
              "exists": {"type": "boolean", "const": true},
              "hop_depth": {"type": "integer", "minimum": 1, "maximum": 5}
            }
          }
        }
      }
    },
    "local_scope": {
      "type": "object",
      "required": ["personal_content_in_committed_file", "claude_local_md_gitignored"],
      "additionalProperties": false,
      "properties": {
        "personal_content_in_committed_file": {"type": "boolean", "const": false},
        "claude_local_md_gitignored": {"type": "boolean", "const": true}
      }
    },
    "subdir_files": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["package", "path", "exists"],
        "additionalProperties": false,
        "properties": {
          "package": {"type": "string", "minLength": 1},
          "path": {"type": "string", "pattern": "/CLAUDE\\.md$"},
          "exists": {"type": "boolean", "const": true}
        }
      }
    },
    "root_has_per_package_commands": {"type": "boolean", "const": false},
    "prohibitions": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["line", "consequence_stated", "emphasised"],
        "additionalProperties": false,
        "properties": {
          "line": {"type": "string", "minLength": 10, "pattern": "(?i)(never|do not|don't|must not)"},
          "consequence_stated": {"type": "boolean", "const": true},
          "emphasised": {"type": "boolean"}
        }
      }
    },
    "emphasis_ratio": {"type": "number", "minimum": 0, "maximum": 0.25},
    "refs_check": {
      "type": "object",
      "required": ["kind", "location", "all_refs_exist"],
      "additionalProperties": false,
      "properties": {
        "kind": {"type": "string", "enum": ["ci-job", "pre-commit-hook"]},
        "location": {"type": "string", "minLength": 3},
        "all_refs_exist": {"type": "boolean", "const": true}
      }
    },
    "reviewer": {"$ref": "#/definitions/handle"},
    "evidence": {"type": "array", "minItems": 1, "items": {"type": "string", "format": "uri"}}
  },
  "if": {"properties": {"layout": {"const": "multi-package"}}},
  "then": {"required": ["subdir_files", "root_has_per_package_commands"]}
}

output-contract.example:
{
  "repo": "acme/platform",
  "layout": "multi-package",
  "root_file": {"line_budget": 100, "budget_declared_in_first_comment": true, "line_count": 84, "within_budget": true, "ci_line_check": true},
  "secrets": {"scanner": "gitleaks", "runs_in_ci": true, "runs_in_pre_commit": true, "clean": true, "referenced_by_name_only": true},
  "commands": [
    {"invocation": "pnpm install --frozen-lockfile", "verbatim": true, "exit_code": 0},
    {"invocation": "pnpm turbo run test --filter=...[origin/main]", "verbatim": true, "exit_code": 0},
    {"invocation": "pnpm turbo run lint", "verbatim": true, "exit_code": 0}
  ],
  "imports": {
    "pasted_repo_content": false,
    "entries": [
      {"path": "CONTRIBUTING.md", "exists": true, "hop_depth": 1},
      {"path": "docs/adr/README.md", "exists": true, "hop_depth": 2}
    ]
  },
  "local_scope": {"personal_content_in_committed_file": false, "claude_local_md_gitignored": true},
  "subdir_files": [
    {"package": "api", "path": "apps/api/CLAUDE.md", "exists": true},
    {"package": "web", "path": "apps/web/CLAUDE.md", "exists": true},
    {"package": "infra", "path": "infra/CLAUDE.md", "exists": true}
  ],
  "root_has_per_package_commands": false,
  "prohibitions": [
    {"line": "never edit /srv/app directly: it is the deploy target, the repo is the source", "consequence_stated": true, "emphasised": true},
    {"line": "do not run pnpm install without --frozen-lockfile: the lockfile drifts and CI fails on the next push", "consequence_stated": true, "emphasised": false},
    {"line": "never commit CLAUDE.local.md: it carries machine paths that break every other clone", "consequence_stated": true, "emphasised": false}
  ],
  "emphasis_ratio": 0.04,
  "refs_check": {"kind": "ci-job", "location": ".github/workflows/claude-md-refs.yml", "all_refs_exist": true},
  "reviewer": "tl:mreyes",
  "evidence": [
    "https://ci.example.com/acme/platform/runs/5120",
    "https://github.com/acme/platform/pull/1187"
  ]
}

{
  "repo": "acme/platform",
  "layout": "multi-package",
  "root_file": {"line_budget": 100, "budget_declared_in_first_comment": false, "line_count": 480, "within_budget": false, "ci_line_check": false},
  "secrets": {"scanner": "gitleaks", "runs_in_ci": true, "runs_in_pre_commit": false, "clean": false, "referenced_by_name_only": false},
  "commands": [
    {"invocation": "run the tests", "verbatim": false, "exit_code": 1}
  ],
  "imports": {
    "pasted_repo_content": true,
    "entries": [
      {"path": "docs/deep/chain/six/hops/README.md", "exists": true, "hop_depth": 6}
    ]
  },
  "local_scope": {"personal_content_in_committed_file": true, "claude_local_md_gitignored": false},
  "root_has_per_package_commands": true,
  "prohibitions": [
    {"line": "IMPORTANT: never touch the config", "consequence_stated": false, "emphasised": true}
  ],
  "emphasis_ratio": 0.6,
  "refs_check": {"kind": "ci-job", "location": ".github/workflows/claude-md-refs.yml", "all_refs_exist": false},
  "reviewer": "team:platform",
  "evidence": [
    "https://ci.example.com/acme/platform/runs/5119"
  ]
}
